    cin.tie(nullptr);

    long long n;
    long long t;
    cin >> n >> t;
    vector<long long> cnt(n);
    for (int i = 0; i < n; i++) cin >> cnt[i];
    vector<long long> w(t);
    for (int i = 0; i < t; i++) cin >> w[i];

    unordered_map<long long, int> edges;
    int pos = 0, best = 0;
    for (int i = 0; i < n; i++) {
        long long s = 0;
        for (int j = 0; j + 1 < cnt[i]; j++) {
            s += w[pos + j];
            best = max(best, ++edges[s]);
        }
        pos += cnt[i];
    }
    cout << n - best << "\n";

