import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long t = Long.parseLong(next());
        long[] cnt = new long[(int) n];
        for (int i = 0; i < cnt.length; i++) cnt[i] = Long.parseLong(next());
        long[] w = new long[(int) t];
        for (int i = 0; i < w.length; i++) w[i] = Long.parseLong(next());

        Map<Long, Integer> edges = new HashMap<>();
        int pos = 0, best = 0;
        for (int i = 0; i < n; i++) {
            long s = 0;
            for (int j = 0; j + 1 < cnt[i]; j++) {
                s += w[pos + j];
                best = Math.max(best, edges.merge(s, 1, Integer::sum));
            }
            pos += (int) cnt[i];
        }
        System.out.println(n - best);
    }
}
